//! Tests for `html/template`: the tables of Go's escape_test.go, content_test.go,
//! js_test.go, css_test.go, url_test.go and html_test.go (replayed from fixtures
//! generated by the Go toolchain) and the API tests of clone_test.go,
//! multi_test.go and template_test.go.

#[path = "../examples/common/template_harness.rs"]
mod harness;

use rust_stdlib::encoding::json;
use rust_stdlib::html::template::{
    self as ht, html_escape, html_escape_string, html_escaper, is_true, js_escape_string, must,
    Css, ErrorCode, Html, HtmlAttr, Js, JsStr, Srcset, Template, TemplateError, Url,
};
use rust_stdlib::text::template::parse::{self, PARSE_COMMENTS};
use rust_stdlib::text::template::value::Value;
use rust_stdlib::text::template::{FuncMap, ToValue};

fn render<D: ToValue + ?Sized>(t: &Template, data: &D) -> String {
    let mut out = Vec::new();
    t.execute(&mut out, data).unwrap_or_else(|e| panic!("{e}"));
    String::from_utf8(out).expect("utf-8")
}

fn render_template<D: ToValue + ?Sized>(
    t: &Template,
    name: &str,
    data: &D,
) -> Result<String, TemplateError> {
    let mut out = Vec::new();
    t.execute_template(&mut out, name, data)?;
    Ok(String::from_utf8(out).expect("utf-8"))
}

/// Every input of Go's escaper tests gets Go's output or Go's error text.
