#[test]
fn clone_growth_is_bounded() {
    let tmpl = must(Template::new("root").parse(r#"<title>{{block "B". }}Arg{{end}}</title>"#));
    let tmpl = must(tmpl.clone_template());
    must(tmpl.parse(r#"{{define "B"}}Text{{end}}"#));
    for _ in 0..10 {
        let _ = tmpl.execute(&mut std::io::sink(), &());
    }
    assert!(tmpl.defined_templates().len() <= 200, "too many templates");
}

#[test]
fn clone_redefined_name() {
    const BASE: &str = "\n{{ define \"a\" -}}<title>{{ template \"b\" . -}}</title>{{ end -}}\n{{ define \"b\" }}{{ end -}}\n";
    let t1 = must(Template::new("a").parse(BASE));
    for i in 0..2 {
        let t2 = must(t1.clone_template());
        let t2 = must(
            t2.associated(&i.to_string())
                .parse(r#"{{ template "a" . }}"#),
        );
        t2.execute(&mut std::io::sink(), &()).unwrap();
    }
}

#[test]
fn clone_pipe() {
    let a =
        must(Template::new("a").parse(r#"{{define "a"}}{{range $v := .A}}{{$v}}{{end}}{{end}}"#));
    let b = must(a.clone_template());
    let data = harness_data_a(&["hi"]);
    assert_eq!(render(&b, &data), "hi");
}

fn harness_data_a(items: &[&str]) -> Value {
    use rust_stdlib::text::template::value::{Field, Type};
    let ty = Type::struct_of(vec![Field::new("A", Type::slice_of(Type::string()))]);
    Value::ptr(Value::struct_(
        &ty,
        vec![Value::slice(
            &Type::string(),
            items.iter().map(Value::string).collect(),
        )],
    ))
}

