#[test]
fn template_clone_of_unparsed() {
    let orig = Template::new("name");
    let clone = orig.clone_template().unwrap();
    assert_eq!(clone.templates().len(), orig.templates().len());
    let parsed = must(clone.parse("stuff"));
    assert_eq!(render(&parsed, &()), "stuff");
}

struct Case {
    root: Template,
}

impl Case {
    fn new() -> Case {
        Case {
            root: Template::new("root"),
        }
    }
    fn must_parse(&self, t: &Template, text: &str) {
        t.parse(text).unwrap_or_else(|e| panic!("parse: {e}"));
    }
    fn must_not_parse(&self, t: &Template, text: &str) {
        assert!(
            t.parse(text).is_err(),
            "unexpected parse success of {text:?}"
        );
    }
    fn must_execute<D: ToValue + ?Sized>(&self, t: &Template, data: &D, want: &str) {
        let mut out = Vec::new();
        t.execute(&mut out, data).unwrap_or_else(|e| panic!("{e}"));
        assert_eq!(String::from_utf8(out).unwrap(), want);
    }
    fn lookup(&self, name: &str) -> Template {
        self.root.lookup(name).expect("template")
    }
}

#[test]
fn redefinition_after_execution_rules() {
    let c = Case::new();
    c.must_parse(&c.root, "foo");
    c.must_execute(&c.root, &(), "foo");
    c.must_not_parse(&c.root, "bar");

    let c = Case::new();
    c.must_parse(&c.root, "");
    c.must_execute(&c.root, &(), "");
    c.must_not_parse(&c.root, "foo");
    c.must_execute(&c.root, &(), "");

    let c = Case::new();
    c.must_parse(
        &c.root,
        r#"{{if .}}<{{template "X"}}>{{end}}{{define "X"}}foo{{end}}"#,
    );
    c.must_execute(&c.root, &0i64, "");
    c.must_not_parse(&c.root, r#"{{define "X"}}bar{{end}}"#);
    c.must_execute(&c.root, &1i64, "&lt;foo>");

    let c = Case::new();
    c.must_parse(&c.root, r#"<{{template "X" .}}>{{define "X"}}foo{{end}}"#);
    c.must_execute(&c.root, &(), "&lt;foo>");
    c.must_not_parse(&c.root, r#"{{define "X"}}bar{{end}}"#);
    c.must_execute(&c.root, &(), "&lt;foo>");

    let c = Case::new();
    c.must_parse(&c.root, r#"{{define "X"}}foo{{end}}"#);
    c.must_execute(&c.lookup("X"), &(), "foo");
    c.must_not_parse(&c.root, r#"{{define "X"}}bar{{end}}"#);
    c.must_execute(&c.lookup("X"), &(), "foo");

    let c = Case::new();
    c.must_parse(&c.root, r#"{{define "X"}}foo{{end}}"#);
    c.must_execute(&c.lookup("X"), &(), "foo");
    c.must_not_parse(&c.lookup("X"), "bar");
    c.must_execute(&c.lookup("X"), &(), "foo");
}

#[test]
fn redefinition_cannot_unsafe_a_template() {
    let c = Case::new();
    c.must_parse(
        &c.root,
        r#"<html><a href="{{template "X"}}">{{define "X"}}{{end}}"#,
    );
    c.must_execute(&c.root, &(), r#"<html><a href="">"#);
    c.must_not_parse(&c.root, r#"{{define "X"}}" bar="baz{{end}}"#);
    c.must_execute(&c.root, &(), r#"<html><a href="">"#);

    let c = Case::new();
    c.must_parse(&c.root, r#"{{template "X"}}{{.}}{{define "X"}}{{end}}"#);
    c.must_execute(&c.root, &42i64, "42");
    c.must_not_parse(&c.root, r#"{{define "X"}}<script>{{end}}"#);
    c.must_execute(&c.root, &42i64, "42");
}

#[test]
fn other_parsers_refuse_after_execute() {
    let c = Case::new();
    c.must_parse(&c.root, "");
    c.must_execute(&c.root, &(), "");
    for e in [
        c.root.parse_files(&["no.template"]).unwrap_err(),
        c.root.parse_glob("*.no.template").unwrap_err(),
        c.root
            .add_parse_tree("t1", (*c.root.tree().unwrap()).clone())
            .unwrap_err(),
    ] {
        assert!(e.to_string().contains("Execute"), "{e}");
    }
}

#[test]
fn numbers() {
    let c = Case::new();
    c.must_parse(&c.root, "{{print 1_2.3_4}} {{print 0x0_1.e_0p+02}}");
    c.must_execute(&c.root, &(), "12.34 7.5");
}

#[test]
fn strings_in_json_scripts_round_trip() {
    let prefix = r#"<script type="application/ld+json">"#;
    let suffix = "</script>";
    let tpl = must(
        Template::new("JS string is JSON string").parse(&format!("{prefix}\"{{{{.}}}}\"{suffix}")),
    );
    for input in [
        "",
        "\u{fffd}",
        "\0",
        "\u{1f}",
        "\t",
        "<>",
        "'\"",
        "ASCII letters",
        "\u{2995}\u{2299}\u{3d6}\u{2299}\u{2994}",
        "\u{1f355}",
    ] {
        let out = render(&tpl, input);
        let trimmed = out
            .strip_prefix(prefix)
            .unwrap()
            .strip_suffix(suffix)
            .unwrap();
        let v = trimmed
            .parse::<json::Value>()
            .unwrap_or_else(|e| panic!("{trimmed:?}: {e}"));
        assert_eq!(
            v.as_str(),
            Some(input),
            "serialization changed the string value"
        );
    }
}

#[test]
fn comments_in_added_trees_are_skipped() {
    let c = Case::new();
    let mut tr = parse::Tree::new("root");
    tr.mode = PARSE_COMMENTS;
    let mut set = std::collections::BTreeMap::new();
    tr.parse(
        "{{/* A comment */}}{{ 1 }}{{/* Another comment */}}",
        "",
        "",
        &mut set,
        &[],
    )
    .unwrap();
    let root = c.root.add_parse_tree("root", tr).unwrap();
    c.must_execute(&root, &(), "1");
}

