#[test]
fn multi_templates() {
    for (src, data, want) in [
        (r#"{{template "x" .}}"#, "ignored", "TEXT"),
        (r#"{{template "dot" .}}"#, "joe", "joe"),
        (r#"{{template "nested" .}}"#, "n<", "n&lt;"),
    ] {
        let template = must(
            Template::new("root")
                .parse("\n\t{{define \"x\"}}TEXT{{end}}\n\t{{define \"dotV\"}}{{.V}}{{end}}\n"),
        );
        must(template.parse("\n\t{{define \"dot\"}}{{.}}{{end}}\n\t{{define \"nested\"}}{{template \"dot\" .}}{{end}}\n"));
        let t = must(template.associated("case").parse(src));
        assert_eq!(render(&t, data), want, "{src}");
    }
}

#[test]
fn redefinition_and_empty_templates() {
    let tmpl = must(Template::new("tmpl1").parse(r#"{{define "test"}}foo{{end}}"#));
    tmpl.parse(r#"{{define "test"}}bar{{end}}"#).unwrap();
    tmpl.associated("tmpl2")
        .parse(r#"{{define "test"}}bar{{end}}"#)
        .unwrap();

    let t1 = Template::new("test");
    t1.parse(r#"{{define "test"}}{{end}}"#).unwrap();
    t1.parse(r#"{{define "test"}}{{/* this is a comment */}}{{end}}"#)
        .unwrap();
    t1.parse(r#"{{define "test"}}foo{{end}}"#).unwrap();

    // html/template keeps text/template's results except for the last case
    // (its "TODO: should want empty" quirk).
    let cases: &[(&[&str], &str, &str)] = &[
        (&["x", "y"], "", "y"),
        (&[""], "once", ""),
        (&["", ""], "twice", ""),
        (&["{{.}}", "{{.}}"], "twice", "twice"),
        (
            &["{{/* a comment */}}", "{{/* a comment */}}"],
            "comment",
            "",
        ),
        (&["{{.}}", ""], "twice", "twice"),
    ];
    for (i, (defs, input, want)) in cases.iter().enumerate() {
        let root = Template::new("root");
        let mut m = None;
        for d in *defs {
            m = Some(root.associated(input).parse(d).unwrap());
        }
        assert_eq!(render(&m.unwrap(), *input), *want, "case {i}");
    }
}

#[test]
fn issue_19294() {
    let inlined = [
        ("stylesheet", r#"{{define "stylesheet"}}stylesheet{{end}}"#),
        ("xhtml", r#"{{block "stylesheet" .}}{{end}}"#),
    ];
    for i in 0..20 {
        let res = must(Template::new("title.xhtml").parse(r#"{{template "xhtml" .}}"#));
        for (name, src) in inlined {
            must(res.associated(name).parse(src));
        }
        let mut out = Vec::new();
        let _ = res.execute(&mut out, &0i64);
        assert_eq!(
            String::from_utf8(out).unwrap(),
            "stylesheet",
            "iteration {i}"
        );
    }
}

#[test]
fn parse_files_glob_and_fs() {
    let dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/template/testdata");
    assert!(ht::parse_files(&["DOES NOT EXIST"]).is_err());
    let t = Template::new("root");
    t.parse_files(&[
        dir.join("file1.tmpl").to_str().unwrap(),
        dir.join("file2.tmpl").to_str().unwrap(),
    ])
    .unwrap();
    assert_eq!(
        render(
            &must(t.associated("c").parse(r#"{{template "nested" .}}"#)),
            "<"
        ),
        "&lt;"
    );

    assert!(ht::parse_glob("DOES NOT EXIST").is_err());
    let err = Template::new("error").parse_glob("[x").unwrap_err();
    assert!(!err.to_string().is_empty());
    let t = Template::new("root");
    t.parse_glob(dir.join("file*.tmpl").to_str().unwrap())
        .unwrap();
    assert_eq!(
        render(&must(t.associated("c").parse(r#"{{template "x" .}}"#)), &()),
        "TEXT"
    );

    let fs = rust_stdlib::io::fs::DirFS::new(dir.clone());
    assert!(ht::parse_fs(&fs, &["DOES NOT EXIST"]).is_err());
    let t = Template::new("root");
    t.parse_fs(&fs, &["file*.tmpl"]).unwrap();
    assert_eq!(
        render(&must(t.associated("c").parse(r#"{{template "x" .}}"#)), &()),
        "TEXT"
    );

    let t = Template::new("root");
    t.parse_files(&[
        dir.join("tmpl1.tmpl").to_str().unwrap(),
        dir.join("tmpl2.tmpl").to_str().unwrap(),
    ])
    .unwrap();
    let t = must(
        t.associated("test")
            .parse(r#"{{template "tmpl1.tmpl"}}{{template "tmpl2.tmpl"}}"#),
    );
    assert_eq!(render(&t, &0i64), "template1\n\ny\ntemplate2\n\nx\n");
}

// ---- error codes, typed content and the exported escapers ------------------

fn escape_error(src: &str) -> ht::Error {
    let t = must(Template::new("z").parse(src));
    match t.execute(&mut std::io::sink(), &()) {
        Err(TemplateError::Escape(e)) => e,
        other => panic!("{src:?}: expected an escaping error, got {other:?}"),
    }
}

#[test]
fn error_codes_and_messages() {
    let cases: &[(&str, ErrorCode, &str)] = &[
        ("{{if .Cond}}<a{{end}}", ErrorCode::BranchEnd, "html/template:z:1:5: {{if}} branches end in different contexts"),
        ("<a b=1 c={{.H}}", ErrorCode::EndContext, "html/template:z: z ends in a non-text context: {stateAttr delimSpaceOrTagEnd urlPartNone jsCtxRegexp [] attrNone elementNone <nil>}"),
        (
            r#"<a href="{{if .F}}/foo?a={{else}}/bar/{{end}}{{.H}}">"#,
            ErrorCode::AmbigContext,
            "html/template:z:1:47: {{.H}} appears in an ambiguous context within a URL",
        ),
        (r#"{{template "foo"}}"#, ErrorCode::NoSuchTemplate, r#"html/template:z:1:11: no such template "foo""#),
        ("<a=foo>", ErrorCode::BadHtml, "html/template:z: expected space, attr name, or end of tag, but got \"=foo>\""),
        (
            "Hello, {{. | html | print}}!",
            ErrorCode::PredefinedEscaper,
            r#"html/template:z:1:9: predefined escaper "html" disallowed in template"#,
        ),
        (
            r#"<a onclick="alert('Hello \"#,
            ErrorCode::PartialEscape,
            r#"html/template:z: unfinished escape sequence in JS string: "Hello \\""#,
        ),
        (
            r#"<a onclick="/foo[\]/"#,
            ErrorCode::PartialCharset,
            r#"html/template:z: unfinished JS regexp charset: "foo[\\]/""#,
        ),
        (
            r#"<script>{{if false}}var x = 1{{end}}/-{{"1.5"}}/i.test(x)</script>"#,
            ErrorCode::SlashAmbig,
            r#"html/template:z: '/' could start a division or regexp: "/-""#,
        ),
        (
            "{{range .Items}}<a{{end}}",
            ErrorCode::BadHtml,
            r#"html/template:z:1: on range loop re-entry: "<" in attribute name: "<a""#,
        ),
    ];
    for (src, code, msg) in cases {
        let e = escape_error(src);
        assert_eq!(e.error_code, *code, "{src}");
        let got = e.to_string();
        // Compare the stable prefix; "z ends in" is the exact Go phrase for
        // the name-qualified form.
        assert!(
            got.starts_with(&msg.replace("html/template:z: z ends", "html/template:z: ends"))
                || got == *msg,
            "{src}:\n got {got:?}\nwant {msg:?}"
        );
    }
    assert_eq!(ErrorCode::Ok as i32, 0);
    assert_eq!(ErrorCode::JsTemplate as i32, 12);
    // A second execution reports the same error.
    let t = must(Template::new("z").parse("<script>foo();"));
    let first = t
        .execute(&mut std::io::sink(), &())
        .unwrap_err()
        .to_string();
    let second = t
        .execute(&mut std::io::sink(), &())
        .unwrap_err()
        .to_string();
    assert_eq!(first, second);
}

#[test]
fn typed_content_is_not_escaped_in_its_context() {
    let t = must(Template::new("x").parse("<p>{{.}}</p>"));
    assert_eq!(render(&t, &Html("<b>x</b>".into())), "<p><b>x</b></p>");
    assert_eq!(render(&t, "<b>x</b>"), "<p>&lt;b&gt;x&lt;/b&gt;</p>");
    let t = must(Template::new("x").parse(r#"<a href="{{.}}" style="{{.}}" onclick="f({{.}})">"#));
    let out = render(&t, &Url("javascript:foo()".into()));
    assert!(
        out.starts_with(r#"<a href="javascript:foo%28%29""#),
        "{out}"
    );
    assert!(
        out.contains("ZgotmplZ"),
        "style and script contexts reject a URL: {out}"
    );
    let t = must(Template::new("x").parse("<div {{.}}>"));
    assert_eq!(
        render(&t, &HtmlAttr(r#"dir="ltr""#.into())),
        r#"<div dir="ltr">"#
    );
    let t = must(Template::new("x").parse("<style>{{.}}</style>"));
    assert_eq!(
        render(&t, &Css("color: red".into())),
        "<style>color: red</style>"
    );
    let t = must(Template::new("x").parse("<script>x = {{.}}</script>"));
    assert_eq!(
        render(&t, &Js("1 + 2".into())),
        "<script>x = 1 + 2</script>"
    );
    let t = must(Template::new("x").parse("<script>x = '{{.}}'</script>"));
    assert_eq!(
        render(&t, &JsStr(r"a\n".into())),
        r"<script>x = 'a\n'</script>"
    );
    let t = must(Template::new("x").parse(r#"<img srcset="{{.}}">"#));
    assert_eq!(
        render(&t, &Srcset("a.png 1x".into())),
        r#"<img srcset="a.png 1x">"#
    );
}

#[test]
fn stringers_errors_and_nil_interfaces_print() {
    use harness::html_data;
    let t = must(Template::new("x").parse("{{.}}"));
    let mut out = Vec::new();
    t.execute_value(&mut out, html_data::html_ref("stringer3").unwrap())
        .unwrap();
    assert_eq!(out, b"string=3");
    let mut out = Vec::new();
    t.execute_value(&mut out, html_data::html_ref("errorer7").unwrap())
        .unwrap();
    assert_eq!(out, b"error=7");
    // A non-empty nil interface prints like an empty one.
    let t = must(Template::new("x").parse("{{.E}}"));
    let mut a = Vec::new();
    let mut b = Vec::new();
    t.execute_value(&mut a, html_data::html_ref("errIface").unwrap())
        .unwrap();
    t.execute_value(&mut b, html_data::html_ref("anyIface").unwrap())
        .unwrap();
    assert_eq!(a, b);
}

#[test]
fn exported_escapers() {
    assert_eq!(
        html_escape_string("<a & 'b'>"),
        "&lt;a &amp; &#39;b&#39;&gt;"
    );
    assert_eq!(js_escape_string("</script>"), "\\u003C/script\\u003E");
    assert_eq!(html_escaper(&[Value::string("x<y")]), "x&lt;y");
    assert_eq!(ht::js_escaper(&[Value::string("'")]), "\\'");
    assert_eq!(ht::url_query_escaper(&[Value::string("a b")]), "a+b");
    let mut out = Vec::new();
    html_escape(&mut out, b"<>").unwrap();
    assert_eq!(out, b"&lt;&gt;");
    assert_eq!(is_true(&Value::int(0)), (false, true));
    assert_eq!(is_true(&Value::string("x")), (true, true));
}

#[test]
fn execute_template_and_lookup_errors() {
    let t = must(Template::new("root").parse(r#"{{define "a"}}<b>{{.}}</b>{{end}}"#));
    assert_eq!(render_template(&t, "a", "<").unwrap(), "<b>&lt;</b>");
    let err = render_template(&t, "nope", &()).unwrap_err();
    assert_eq!(err.to_string(), r#"html/template: "nope" is undefined"#);
    let t2 = Template::new("empty");
    let err = t2.execute(&mut std::io::sink(), &()).unwrap_err();
    assert_eq!(
        err.to_string(),
        r#"template: "empty" is an incomplete or empty template"#
    );
}

#[test]
fn deeply_nested_html_is_escaped_without_overflow() {
    let depth = 400;
    let src = format!(
        "{}<p>{{{{.}}}}</p>{}",
        "{{if true}}".repeat(depth),
        "{{end}}".repeat(depth)
    );
    let t = must(Template::new("t").parse(&src));
    assert_eq!(render(&t, "<"), "<p>&lt;</p>");
}

#[test]
fn parse_fs_from_embed_fs() {
    static FILES: &[(&str, &[u8])] = &[
        ("templates/page.html", b"<p>{{template \"x\" .}}</p>"),
        ("templates/x.html", b"{{define \"x\"}}[{{.}}]{{end}}"),
        ("templates/skip.txt", b"nope"),
    ];
    let fsys = rust_stdlib::embed::FS::new(FILES);
    let t = ht::new("p").parse_fs(&fsys, &["templates/*.html"]).unwrap();
    let mut out = Vec::new();
    t.execute_template(&mut out, "page.html", &"a&b").unwrap();
    assert_eq!(String::from_utf8(out).unwrap(), "<p>[a&amp;b]</p>");
    assert!(ht::parse_fs(&fsys, &["templates/*.css"]).is_err());
}
